"use client"

import { useState, useEffect } from "react"
import { useNavigate, useLocation } from "react-router-dom"
import {
  Home,
  LogOut,
  User,
  ChevronLeft,
  ChevronRight,
  Menu,
  ChevronDown,
  Calendar,
  FileText,
  Utensils,
  Clock,
  GraduationCap,
} from "lucide-react"

export default function InternSidebar({ isCollapsed, setIsCollapsed, closeMenu }) {
  const navigate = useNavigate()
  const location = useLocation()
  const [isMobile, setIsMobile] = useState(false)
  const [isAbsenceOpen, setIsAbsenceOpen] = useState(false)
  const [isMealsOpen, setIsMealsOpen] = useState(false)

  useEffect(() => {
    const checkIfMobile = () => {
      setIsMobile(window.innerWidth < 768)
      if (window.innerWidth < 768) {
        setIsCollapsed(true)
      }
    }

    checkIfMobile()
    window.addEventListener("resize", checkIfMobile)
    return () => window.removeEventListener("resize", checkIfMobile)
  }, [setIsCollapsed])

  useEffect(() => {
    const absenceRoutes = ["/intern/report-history", "/intern/add-report"]
    const mealRoutes = ["/MealsForNextDayI"]
    if (absenceRoutes.includes(location.pathname)) {
      setIsAbsenceOpen(true)
    }
    if (mealRoutes.includes(location.pathname)) {
      setIsMealsOpen(true)
    }
  }, [location.pathname])

  const handleLogout = () => {
    localStorage.removeItem("token")
    localStorage.removeItem("role")
    navigate("/")
  }

  const AbsenceItems = [
    { title: "Historique des absences", icon: Clock, href: "/intern/absences-history" }, // Clock for history
    { title: "Demander un absence", icon: FileText, href: "/intern/add-absences" }, // FileText for adding report
    { title: "Historique des rapports", icon: GraduationCap, href: "/intern/report-history" },
  ]

  const MealItems = [{ title: "Repas de demain", icon: Utensils, href: "/MealsForNextDayI" }]

  const navItems = [{ title: "Tableau de bord", icon: Home, href: "/InternDashboard" }]

  const bottomNavItems = [{ title: "Compte", icon: User, href: "/accountintern" }]

  const toggleSidebar = () => {
    setIsCollapsed(!isCollapsed)
    if (closeMenu) closeMenu()
  }

  const toggleAbsenceSection = () => {
    setIsAbsenceOpen(!isAbsenceOpen)
    if (isCollapsed) setIsCollapsed(false)
  }

  const toggleMealsSection = () => {
    setIsMealsOpen(!isMealsOpen)
    if (isCollapsed) setIsCollapsed(false)
  }

  return (
    <div
      className={`fixed inset-y-0 left-0 z-50 flex flex-col mt-[56px] bg-[#F5F6FA] border-r border-[#C8A45D/30] transition-all duration-300 ease-in-out shadow-lg ${
        isCollapsed ? "w-14 sm:w-16" : "w-52 sm:w-64"
      }`}
    >
      <button
        onClick={toggleSidebar}
        className="absolute -right-3 top-20 bg-white border border-[#C8A45D/30] rounded-full p-1.5 shadow-md z-10 hidden md:flex hover:bg-[#C8A45D/20] transition-colors"
      >
        {isCollapsed ? (
          <ChevronRight size={16} className="text-[#00717F]" />
        ) : (
          <ChevronLeft size={16} className="text-[#00717F]" />
        )}
      </button>

      <div className="flex flex-col h-full">
        <div className="p-2">
          <button
            onClick={toggleSidebar}
            className="md:hidden w-full flex items-center justify-center p-2 rounded-md text-[#00717F] hover:bg-[#C8A45D/20] transition-colors"
          >
            <Menu size={20} />
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto px-2 py-2">
          <ul className="space-y-1">
            {navItems.map((item) => {
              const isActive = location.pathname === item.href
              return (
                <li key={item.title}>
                  <button
                    onClick={() => navigate(item.href)}
                    className={`flex items-center w-full rounded-md px-2 sm:px-3 py-2 sm:py-2.5 text-xs sm:text-sm font-medium transition-all ${
                      isActive
                        ? "bg-[#C8A45D/20] text-[#00717F] shadow-sm"
                        : "text-#333333 hover:bg-[#C8A45D/20]/50 hover:text-[#00717F]"
                    }`}
                  >
                    <item.icon className={`h-4 w-4 sm:h-5 sm:w-5 ${isActive ? "text-[#00717F]" : "text-gray-500"}`} />
                    {!isCollapsed && (
                      <span className="ml-2 sm:ml-3 truncate transition-opacity duration-200">{item.title}</span>
                    )}
                  </button>
                </li>
              )
            })}

            {/* Absences Section */}
            <li className="mt-3 sm:mt-4">
              <button
                onClick={toggleAbsenceSection}
                className={`flex items-center justify-between w-full rounded-md px-2 sm:px-3 py-2 sm:py-2.5 text-xs sm:text-sm font-medium transition-all ${
                  isAbsenceOpen
                    ? "bg-[#00717F] text-white shadow-sm"
                    : "text-[#333333] hover:bg-[#C8A45D]/10 hover:text-[#00717F]"
                }`}
              >
                <div className="flex items-center">
                  <Calendar className={`h-4 w-4 sm:h-5 sm:w-5 ${isAbsenceOpen ? "text-white" : "text-gray-500"}`} />
                  {!isCollapsed && (
                    <span className="ml-2 sm:ml-3 truncate transition-opacity duration-200">Absences</span>
                  )}
                </div>
                {!isCollapsed && (
                  <ChevronDown
                    className={`h-3 w-3 sm:h-4 sm:w-4 transition-transform duration-200 ${
                      isAbsenceOpen ? "rotate-180 text-white" : "text-gray-500"
                    }`}
                  />
                )}
              </button>
              {isAbsenceOpen && (
                <ul className={`mt-1 space-y-1 ${isCollapsed ? "pl-0" : "pl-3 sm:pl-4"}`}>
                  {AbsenceItems.map((item) => {
                    const isActive = location.pathname === item.href
                    return (
                      <li key={item.title}>
                        <button
                          onClick={() => navigate(item.href)}
                          className={`flex items-center w-full rounded-md px-2 sm:px-3 py-1.5 sm:py-2.5 text-xs sm:text-sm font-medium transition-all ${
                            isActive
                              ? "bg-[#C8A45D/20] text-[#00717F] shadow-sm"
                              : "text-#333333 hover:bg-[#C8A45D/20]/50 hover:text-[#00717F]"
                          }`}
                        >
                          <item.icon
                            className={`h-4 w-4 sm:h-5 sm:w-5 ${isActive ? "text-[#00717F]" : "text-gray-500"}`}
                          />
                          {!isCollapsed && (
                            <span className="ml-2 sm:ml-3 truncate transition-opacity duration-200">{item.title}</span>
                          )}
                        </button>
                      </li>
                    )
                  })}
                </ul>
              )}
            </li>

            {/* Repas Section */}
            <li className="mt-3 sm:mt-4">
              <button
                onClick={toggleMealsSection}
                className={`flex items-center justify-between w-full rounded-md px-2 sm:px-3 py-2 sm:py-2.5 text-xs sm:text-sm font-medium transition-all ${
                  isMealsOpen
                    ? "bg-[#00717F] text-white shadow-sm"
                    : "text-#333333 hover:bg-[#C8A45D/20]/50 hover:text-[#00717F]"
                }`}
              >
                <div className="flex items-center">
                  <Utensils className={`h-4 w-4 sm:h-5 sm:w-5 ${isMealsOpen ? "text-white" : "text-gray-500"}`} />
                  {!isCollapsed && <span className="ml-2 sm:ml-3 truncate transition-opacity duration-200">Repas</span>}
                </div>
                {!isCollapsed && (
                  <ChevronDown
                    className={`h-3 w-3 sm:h-4 sm:w-4 transition-transform duration-200 ${
                      isMealsOpen ? "rotate-180 text-white" : "text-gray-500"
                    }`}
                  />
                )}
              </button>
              {isMealsOpen && (
                <ul className={`mt-1 space-y-1 ${isCollapsed ? "pl-0" : "pl-3 sm:pl-4"}`}>
                  {MealItems.map((item) => {
                    const isActive = location.pathname === item.href
                    return (
                      <li key={item.title}>
                        <button
                          onClick={() => navigate(item.href)}
                          className={`flex items-center w-full rounded-md px-2 sm:px-3 py-1.5 sm:py-2.5 text-xs sm:text-sm font-medium transition-all ${
                            isActive
                              ? "bg-[#C8A45D/20] text-[#00717F] shadow-sm"
                              : "text-#333333 hover:bg-[#C8A45D/20]/50 hover:text-[#00717F]"
                          }`}
                        >
                          <item.icon
                            className={`h-4 w-4 sm:h-5 sm:w-5 ${isActive ? "text-[#00717F]" : "text-gray-500"}`}
                          />
                          {!isCollapsed && (
                            <span className="ml-2 sm:ml-3 truncate transition-opacity duration-200">{item.title}</span>
                          )}
                        </button>
                      </li>
                    )
                  })}
                </ul>
              )}
            </li>
          </ul>
        </nav>

        <div className="mt-auto border-t border-[#C8A45D/30] px-2 py-3 sm:py-4">
          <ul className="space-y-1">
            {bottomNavItems.map((item) => (
              <li key={item.title}>
                <button
                  onClick={() => navigate(item.href)}
                  className="flex items-center w-full rounded-md px-2 sm:px-3 py-2 sm:py-2.5 text-xs sm:text-sm font-medium text-#333333 hover:bg-[#C8A45D/20]/50 hover:text-[#00717F] transition-all"
                >
                  <item.icon className="h-4 w-4 sm:h-5 sm:w-5 text-gray-500" />
                  {!isCollapsed && <span className="ml-2 sm:ml-3 transition-opacity duration-200">{item.title}</span>}
                </button>
              </li>
            ))}
            <li>
              <button
                onClick={handleLogout}
                className="flex items-center w-full rounded-md px-2 sm:px-3 py-2 sm:py-2.5 text-xs sm:text-sm font-medium text-#333333 hover:bg-red-50 hover:text-red-600 transition-all"
              >
                <LogOut className="h-4 w-4 sm:h-5 sm:w-5 text-gray-500" />
                {!isCollapsed && <span className="ml-2 sm:ml-3 transition-opacity duration-200">Déconnexion</span>}
              </button>
            </li>
          </ul>
        </div>
      </div>
    </div>
  )
}
